1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = { id: number; name: string; clientId: number; clientName: string };
11	type Invoice = {
12	  id: number;
13	  projectId: number;
14	  amount: number;
15	  status: string;
16	  issuedDate: string;
17	  dueDate: string;
18	};
19	type Task = { id: number; projectId: number; title: string; done: boolean };
20	
21	type LineItem = {
22	  id: number;
23	  invoiceId: number;
24	  description: string;
25	  qty: number;
26	  unitPrice: number;
27	};
28	
29	function money(amount: number): string {
30	  return `$${Number(amount).toFixed(2)}`;
31	}
32	
33	// One charge line while it is being edited on screen: the fields are held as raw strings so the
34	// inputs stay controlled and the total can recompute live as they change.
35	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
36	
37	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
38	// many, price each), the total worked out for you, and a form to add another line. Each line can be
39	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
40	// own line-item state, scoped to the one invoice it is showing.
41	function InvoiceDetail({
42	  invoiceId,
43	  onChange,
44	  onClose,
45	}: {
46	  invoiceId: number;
47	  onChange: () => void;
48	  onClose: () => void;
49	}) {
50	  const [items, setItems] = useState<EditItem[]>([]);
51	  const [description, setDescription] = useState('');
52	  const [qty, setQty] = useState('');
53	  const [unitPrice, setUnitPrice] = useState('');
54	
55	  async function load() {
56	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
57	    const rows: LineItem[] = await res.json();
58	    setItems(
59	      rows.map((li) => ({
60	        id: li.id,
61	        description: li.description,
62	        qty: String(li.qty),
63	        unitPrice: String(li.unitPrice),
64	      })),
65	    );
66	  }
67	
68	  useEffect(() => {
69	    void load();
70	  }, [invoiceId]);
71	
72	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
73	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
74	  }
75	
76	  function amountOf(li: EditItem): number {
77	    const line = Number(li.qty) * Number(li.unitPrice);
78	    return Number.isFinite(line) ? line : 0;
79	  }
80	
81	  async function save(li: EditItem) {
82	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
83	      return;
84	    }
85	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
86	      method: 'POST',
87	      headers: { 'Content-Type': 'application/json' },
88	      body: JSON.stringify({
89	        description: li.description,
90	        qty: Number(li.qty),
91	        unitPrice: Number(li.unitPrice),
92	      }),
93	    });
94	    await load();
95	    onChange();
96	  }
97	
98	  async function remove(id: number) {
99	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
100	    await load();
101	    onChange();
102	  }
103	
104	  async function submit(e: React.FormEvent) {
105	    e.preventDefault();
106	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
107	      return;
108	    }
109	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
110	      method: 'POST',
111	      headers: { 'Content-Type': 'application/json' },
112	      body: JSON.stringify({
113	        description,
114	        qty: Number(qty),
115	        unitPrice: Number(unitPrice),
116	      }),
117	    });
118	    setDescription('');
119	    setQty('');
120	    setUnitPrice('');
121	    await load();
122	    onChange();
123	  }
124	
125	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
126	
127	  return (
128	    <section data-testid="invoice-detail">
129	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
130	        Back to invoices
131	      </button>
132	
133	      <table data-testid="invoice-lineitems-table">
134	        <tbody>
135	          {items.map((li) => (
136	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
137	              <td>
138	                <input
139	                  data-testid="lineitem-description"
140	                  value={li.description}
141	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
142	                />
143	              </td>
144	              <td>
145	                <input
146	                  data-testid="lineitem-qty"
147	                  value={li.qty}
148	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
149	                />
150	              </td>
151	              <td>
152	                <input
153	                  data-testid="lineitem-unitprice"
154	                  value={li.unitPrice}
155	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
156	                />
157	              </td>
158	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
159	              <td>
160	                <button
161	                  data-testid={`lineitem-save-${li.id}`}
162	                  type="button"
163	                  onClick={() => save(li)}
164	                >
165	                  Save
166	                </button>
167	                <button
168	                  data-testid={`lineitem-remove-${li.id}`}
169	                  type="button"
170	                  onClick={() => remove(li.id)}
171	                >
172	                  Remove
173	                </button>
174	              </td>
175	            </tr>
176	          ))}
177	        </tbody>
178	      </table>
179	
180	      <p data-testid="invoice-amount">{money(total)}</p>
181	
182	      <form data-testid="lineitem-form" onSubmit={submit}>
183	        <input
184	          data-testid="lineitem-form-description"
185	          placeholder="Description"
186	          value={description}
187	          onChange={(e) => setDescription(e.target.value)}
188	        />
189	        <input
190	          data-testid="lineitem-form-qty"
191	          placeholder="How many"
192	          value={qty}
193	          onChange={(e) => setQty(e.target.value)}
194	        />
195	        <input
196	          data-testid="lineitem-form-unitprice"
197	          placeholder="Price each"
198	          value={unitPrice}
199	          onChange={(e) => setUnitPrice(e.target.value)}
200	        />
201	        <button data-testid="lineitem-form-submit" type="submit">
202	          Add line item
203	        </button>
204	      </form>
205	    </section>
206	  );
207	}
208	
209	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
210	// own invoice state, scoped to the one project it is showing.
211	function ProjectDetail({ project }: { project: Project }) {
212	  const [invoices, setInvoices] = useState<Invoice[]>([]);
213	  const [tasks, setTasks] = useState<Task[]>([]);
214	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
215	  const [amount, setAmount] = useState('');
216	  const [amountError, setAmountError] = useState('');
217	  const [sortByDue, setSortByDue] = useState(false);
218	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
219	
220	  async function load() {
221	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
222	    setInvoices(await res.json());
223	  }
224	
225	  async function loadTasks() {
226	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
227	    setTasks(await res.json());
228	  }
229	
230	  useEffect(() => {
231	    void load();
232	    void loadTasks();
233	  }, [project.id]);
234	
235	  async function toggleTask(id: number) {
236	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
237	    await loadTasks();
238	  }
239	
240	  async function submit(e: React.FormEvent) {
241	    e.preventDefault();
242	    const value = Number(amount);
243	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
244	      setAmountError('Amount must be more than zero');
245	      return;
246	    }
247	    setAmountError('');
248	    await fetch('/api/invoices', {
249	      method: 'POST',
250	      headers: { 'Content-Type': 'application/json' },
251	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
252	    });
253	    setAmount('');
254	    await load();
255	  }
256	
257	  async function send(id: number) {
258	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
259	    await load();
260	  }
261	
262	  async function pay(id: number) {
263	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
264	    await load();
265	  }
266	
267	  const shownTasks = tasks.filter((t) =>
268	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
269	  );
270	
271	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
272	  const shownInvoices = sortByDue
273	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
274	    : invoices;
275	
276	  return (
277	    <section data-testid="project-detail">
278	      <h2 data-testid="project-detail-name">{project.name}</h2>
279	
280	      <select
281	        data-testid="task-filter"
282	        value={taskFilter}
283	        onChange={(e) => setTaskFilter(e.target.value as 'ALL' | 'OPEN' | 'DONE')}
284	      >
285	        <option value="ALL">All tasks</option>
286	        <option value="OPEN">Open</option>
287	        <option value="DONE">Done</option>
288	      </select>
289	
290	      <table data-testid="project-tasks-table">
291	        <tbody>
292	          {shownTasks.map((t) => (
293	            <tr key={t.id} data-testid={`task-row-${t.id}`}>
294	              <td data-testid="task-title">{t.title}</td>
295	              <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
296	              <td>
297	                <button data-testid={`task-toggle-${t.id}`} onClick={() => toggleTask(t.id)}>
298	                  {t.done ? 'Reopen' : 'Tick off'}
299	                </button>
300	              </td>
301	            </tr>
302	          ))}
303	        </tbody>
304	      </table>
305	
306	      <form data-testid="invoice-form" onSubmit={submit}>
307	        <input
308	          data-testid="invoice-form-amount"
309	          placeholder="Amount"
310	          value={amount}
311	          onChange={(e) => setAmount(e.target.value)}
312	        />
313	        <button data-testid="invoice-form-submit" type="submit">
314	          Add invoice
315	        </button>
316	        {amountError && (
317	          <p data-testid="invoice-form-amount-error" role="alert">
318	            {amountError}
319	          </p>
320	        )}
321	      </form>
322	
323	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
324	        Sort by due date
325	      </button>
326	
327	      {openInvoiceId === null ? (
328	        <>
329	          <table data-testid="project-invoices-table">
330	            <tbody>
331	              {shownInvoices.map((inv) => (
332	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
333	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
334	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
335	                  <td data-testid="invoice-due">{inv.dueDate}</td>
336	                  <td data-testid="invoice-status">{inv.status}</td>
337	                  <td>
338	                    <button
339	                      data-testid={`invoice-open-${inv.id}`}
340	                      onClick={() => setOpenInvoiceId(inv.id)}
341	                    >
342	                      Open
343	                    </button>
344	                    {inv.status === 'DRAFT' && (
345	                      <button data-testid={`invoice-send-${inv.id}`} onClick={() => send(inv.id)}>
346	                        Send
347	                      </button>
348	                    )}
349	                    {inv.status === 'SENT' && (
350	                      <button data-testid={`invoice-pay-${inv.id}`} onClick={() => pay(inv.id)}>
351	                        Mark paid
352	                      </button>
353	                    )}
354	                  </td>
355	                </tr>
356	              ))}
357	            </tbody>
358	          </table>
359	
360	          <p data-testid="project-invoices-total">{money(total)}</p>
361	        </>
362	      ) : (
363	        <InvoiceDetail
364	          invoiceId={openInvoiceId}
365	          onChange={load}
366	          onClose={() => setOpenInvoiceId(null)}
367	        />
368	      )}
369	    </section>
370	  );
371	}
372	
373	function ProjectsPage() {
374	  const [projects, setProjects] = useState<Project[]>([]);
375	  const [clients, setClients] = useState<Client[]>([]);
376	  const [name, setName] = useState('');
377	  const [clientId, setClientId] = useState('');
378	  const [openId, setOpenId] = useState<number | null>(null);
379	
380	  async function loadProjects() {
381	    const res = await fetch('/api/projects');
382	    setProjects(await res.json());
383	  }
384	
385	  async function loadClients() {
386	    const res = await fetch('/api/clients');
387	    setClients(await res.json());
388	  }
389	
390	  useEffect(() => {
391	    void loadProjects();
392	    void loadClients();
393	  }, []);
394	
395	  async function submit(e: React.FormEvent) {
396	    e.preventDefault();
397	    if (!name.trim() || !clientId) {
398	      return;
399	    }
400	    await fetch('/api/projects', {
401	      method: 'POST',
402	      headers: { 'Content-Type': 'application/json' },
403	      body: JSON.stringify({ name, clientId: Number(clientId) }),
404	    });
405	    setName('');
406	    setClientId('');
407	    await loadProjects();
408	  }
409	
410	  async function remove(id: number) {
411	    await fetch(`/api/projects/${id}/delete`, { method: 'POST' });
412	    if (openId === id) {
413	      setOpenId(null);
414	    }
415	    await loadProjects();
416	  }
417	
418	  const open = projects.find((p) => p.id === openId) ?? null;
419	
420	  return (
421	    <section data-testid="projects">
422	      <form data-testid="project-form" onSubmit={submit}>
423	        <input
424	          data-testid="project-form-name"
425	          placeholder="Project name"
426	          value={name}
427	          onChange={(e) => setName(e.target.value)}
428	        />
429	        <select
430	          data-testid="project-form-client"
431	          value={clientId}
